   raise exception 'count_capacity_exceeded'using errcode='P0001',detail='',hint='';end if;
  actual_members:=actual_members||jsonb_build_array(member_value);
 end loop;
 if actual_members::text is distinct from expected_members::text then
  raise exception 'count_source_invalid'using errcode='P0001',detail='',hint='';end if;
 result_value:=jsonb_build_object('schema_version',1,'domain','lrv-controlled-count-live-causes-v1',
  'product_id',p_product,'causes',expected_causes,'membership',expected_members);
 if octet_length(result_value::text)>1048576 then
  raise exception 'count_capacity_exceeded'using errcode='P0001',detail='',hint='';end if;
